# same thinning, count connectivity with redundant diagonals suppressed
from PIL import Image
import numpy as np
from scipy.ndimage import label,find_objects
im=np.asarray(Image.open('/app/target.png').convert('RGB'),float); colors={'black':(20,20,24),'red':(208,32,28),'green':(27,138,58)}
def thin(a):
 a=a.copy().astype(bool)
 while True:
  changed=False
  for ph in (0,1):
   p=np.pad(a,1); n=[p[:-2,1:-1],p[:-2,2:],p[1:-1,2:],p[2:,2:],p[2:,1:-1],p[2:,:-2],p[1:-1,:-2],p[:-2,:-2]]
   s=sum(n); t=sum((n[i]==0)&(n[(i+1)%8]==1) for i in range(8)); c=a&(s>=2)&(s<=6)&(t==1)
   if ph==0:c &= ~(n[0]&n[2]&n[4]) & ~(n[2]&n[4]&n[6])
   else:c &= ~(n[0]&n[2]&n[6]) & ~(n[0]&n[4]&n[6])
   if c.any():a[c]=False;changed=True
  if not changed:break
 return a
for name,c in colors.items():
 lab,n=label(np.linalg.norm(im-c,axis=2)<65,np.ones((3,3)))
 print('\n',name)
 for i,s in enumerate(find_objects(lab),1):
  if s is None:continue
  a=thin(lab[s]==i)
  yy,xx=np.where(a); p=np.pad(a,1); deg=[]
  for y,x in zip(yy,xx):
   z=0
   for dy in [-1,0,1]:
    for dx in [-1,0,1]:
     if not (dy or dx) or not p[y+1+dy,x+1+dx]:continue
     if dy and dx and (p[y+1+dy,x+1] or p[y+1,x+1+dx]):continue
     z+=1
   deg.append(z)
  deg=np.array(deg)
  if a.sum()>100 or name=='green':print(i,a.sum(),'degree',np.unique(deg,return_counts=True))
